from typing import List

def parse_music(music_string: str) -> List[int]:
    """ Interpret a string of musical notes in ASCII format and return a list of integers indicating the number of beats each note lasts.

    Key:
    'o' - whole note, 4 beats
    'o|' - half note, 2 beats
    '.|' - quarter note, 1 beat
    """
    note_mapping = {'o': 4, 'o|': 2, '.|': 1}
    notes = music_string.split()
    beats_list = [note_mapping[note] for note in notes]

    return beats_list
